import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D9E58p8B.js";const p=JSON.parse('{"title":"Overlay","description":"","frontmatter":{"title":"Overlay"},"headers":[],"relativePath":"reference/overlay.md","filePath":"reference/overlay.md"}'),s={name:"reference/overlay.md"};function d(i,e,n,l,u,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="overlay-montrer-ce-que-fait-l-ia" tabindex="-1">Overlay : montrer ce que fait l&#39;IA <a class="header-anchor" href="#overlay-montrer-ce-que-fait-l-ia" aria-label="Permalink to &quot;Overlay : montrer ce que fait l&#39;IA&quot;">​</a></h1><p>L&#39;Overlay est la couche visuelle que Daimon dessine par-dessus l&#39;écran pour que la personne devant la machine voie où l&#39;IA regarde et agit : cadre, projecteur, curseur, bandeau. Il est purement présentationnel.</p><p>Les cinq outils ont les mêmes propriétés :</p><ul><li>ils n&#39;ont aucun niveau d&#39;autorisation et ne sont pas soumis au plafond ;</li><li>ils ne bloquent jamais et n&#39;échouent jamais ;</li><li>ils renvoient toujours <code>{&quot;ok&quot;: true}</code>, <strong>même si aucune fenêtre d&#39;overlay n&#39;est en cours d&#39;exécution</strong> : l&#39;ordre est alors simplement abandonné. Un <code>ok</code> ne prouve donc pas que la marque est visible ;</li><li>le réglage « Présence à l&#39;écran » du panneau active l&#39;overlay.</li><li>par défaut (<code>anti_feedback</code> vaut <code>true</code> dans la configuration), les marques de l&#39;Overlay sont <strong>invisibles de toute capture d&#39;écran</strong>, y compris <a href="./vue.html#vue-snapshot"><code>vue_snapshot</code></a> : l&#39;IA ne voit jamais ses propres marques. Vous les voyez à l&#39;écran, mais elles n&#39;apparaissent pas dans une capture ; c&#39;est pourquoi cette documentation n&#39;en montre aucune. Sous macOS, l&#39;overlay est une fenêtre sans interaction qui couvre l&#39;écran principal.</li></ul><div class="warning custom-block"><p class="custom-block-title">Unité des coordonnées</p><p>Ici, les coordonnées sont des <strong>pixels globaux bruts</strong>, déjà résolus par vous. Il n&#39;y a ni <code>space</code>, ni <code>display</code>, ni <code>region</code> (contrairement aux Mains, qui parlent en points). Ne passez pas de pixels d&#39;image : convertissez-les d&#39;abord avec <a href="./vue.html#vue-resolve"><code>vue_resolve</code></a>.</p></div><h2 id="helper" tabindex="-1">Le helper de l&#39;Overlay <a class="header-anchor" href="#helper" aria-label="Permalink to &quot;Le helper de l&#39;Overlay {#helper}&quot;">​</a></h2><p>Les marques sont dessinées par un processus à part, le <strong>helper</strong> (<code>Daimon overlay</code>). Il se termine de lui-même : 60 secondes après son lancement s&#39;il n&#39;a eu aucun client, et 3 secondes après le départ de son dernier client.</p><p>Le client <strong>relance le helper</strong> quand un envoi échoue faute de helper, à condition que « Présence à l&#39;écran » soit activé, et au plus une fois toutes les 5 secondes. Activer « Présence à l&#39;écran » dans le panneau lance aussi le helper ; le désactiver ne l&#39;arrête pas et ne le relance pas.</p><p>Pour savoir si le helper vit, appelez <a href="./diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> et lisez la clé <code>overlay</code>. Le journal <code>overlay.log</code>, dans le dossier de données de Daimon, note <code>overlay: bound</code>, puis <code>overlay: start enabled=&lt;true|false&gt;</code> au démarrage, et <code>overlay: exit reason=&lt;idle|startup&gt;</code> à la sortie, chaque ligne précédée d&#39;un horodatage UTC.</p><table tabindex="0"><thead><tr><th>Outil</th><th>Rôle</th><th>Niveau</th></tr></thead><tbody><tr><td><a href="#overlay-highlight"><code>overlay_highlight</code></a></td><td>Cadre arrondi autour d&#39;une région, avec libellé</td><td>aucun</td></tr><tr><td><a href="#overlay-spotlight"><code>overlay_spotlight</code></a></td><td>Assombrit l&#39;écran sauf une région</td><td>aucun</td></tr><tr><td><a href="#overlay-cursor"><code>overlay_cursor</code></a></td><td>Halo de curseur synthétique</td><td>aucun</td></tr><tr><td><a href="#overlay-banner"><code>overlay_banner</code></a></td><td>Bandeau coloré selon un niveau</td><td>aucun</td></tr><tr><td><a href="#overlay-clear"><code>overlay_clear</code></a></td><td>Efface toutes les marques</td><td>aucun</td></tr></tbody></table><h2 id="overlay-highlight" tabindex="-1">overlay_highlight <a class="header-anchor" href="#overlay-highlight" aria-label="Permalink to &quot;overlay_highlight {#overlay-highlight}&quot;">​</a></h2><p>Dessine un rectangle arrondi stylé, avec un libellé facultatif, autour d&#39;une région.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>x</code></td><td>entier</td><td>aucun</td><td><strong>oui</strong></td><td>Bord gauche</td></tr><tr><td><code>y</code></td><td>entier</td><td>aucun</td><td><strong>oui</strong></td><td>Bord haut</td></tr><tr><td><code>width</code></td><td>entier</td><td>aucun</td><td><strong>oui</strong></td><td>Largeur</td></tr><tr><td><code>height</code></td><td>entier</td><td>aucun</td><td><strong>oui</strong></td><td>Hauteur</td></tr><tr><td><code>label</code></td><td>chaîne</td><td><code>&quot;&quot;</code></td><td>non</td><td>Libellé affiché avec le cadre</td></tr></tbody></table><p><strong>Exemple d&#39;appel</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">220</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bouton Envoyer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Retour</strong> : <code>{&quot;ok&quot;: true}</code>.</p><h2 id="overlay-spotlight" tabindex="-1">overlay_spotlight <a class="header-anchor" href="#overlay-spotlight" aria-label="Permalink to &quot;overlay_spotlight {#overlay-spotlight}&quot;">​</a></h2><p>Assombrit l&#39;écran sauf un trou dégagé sur la région.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>x</code>, <code>y</code></td><td>entier</td><td>aucun</td><td><strong>oui</strong></td><td>Coin haut-gauche de la région</td></tr><tr><td><code>width</code>, <code>height</code></td><td>entier</td><td>aucun</td><td><strong>oui</strong></td><td>Dimensions de la région</td></tr></tbody></table><p><strong>Exemple d&#39;appel</strong> : <code>{ &quot;x&quot;: 400, &quot;y&quot;: 300, &quot;width&quot;: 220, &quot;height&quot;: 60 }</code></p><p><strong>Retour</strong> : <code>{&quot;ok&quot;: true}</code>.</p><h2 id="overlay-cursor" tabindex="-1">overlay_cursor <a class="header-anchor" href="#overlay-cursor" aria-label="Permalink to &quot;overlay_cursor {#overlay-cursor}&quot;">​</a></h2><p>Place le halo de curseur synthétique sur un point global.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>x</code>, <code>y</code></td><td>entier</td><td>aucun</td><td><strong>oui</strong></td><td>Point</td></tr></tbody></table><p><strong>Exemple d&#39;appel</strong> : <code>{ &quot;x&quot;: 510, &quot;y&quot;: 330 }</code></p><p><strong>Retour</strong> : <code>{&quot;ok&quot;: true}</code>.</p><h2 id="overlay-banner" tabindex="-1">overlay_banner <a class="header-anchor" href="#overlay-banner" aria-label="Permalink to &quot;overlay_banner {#overlay-banner}&quot;">​</a></h2><p>Affiche un bandeau coloré selon un niveau, avec un texte.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>text</code></td><td>chaîne</td><td>aucun</td><td><strong>oui</strong></td><td>Texte du bandeau</td></tr><tr><td><code>level</code></td><td>chaîne</td><td><code>&quot;L1&quot;</code></td><td>non</td><td>Couleur : <code>default</code>, <code>L1</code>, <code>L2</code>, <code>L3</code>, <code>L4</code> ou <code>gate</code></td></tr></tbody></table><p><strong>Exemple d&#39;appel</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Daimon remplit le formulaire&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;L2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Retour</strong> : <code>{&quot;ok&quot;: true}</code>.</p><p><strong>Pièges</strong> : un niveau inconnu retombe sur <code>default</code>, sans erreur.</p><h2 id="overlay-clear" tabindex="-1">overlay_clear <a class="header-anchor" href="#overlay-clear" aria-label="Permalink to &quot;overlay_clear {#overlay-clear}&quot;">​</a></h2><p>Efface toutes les marques d&#39;overlay actuellement à l&#39;écran.</p><p><strong>Paramètres</strong> : aucun. <strong>Retour</strong> : <code>{&quot;ok&quot;: true}</code>.</p>',36)])])}const g=t(s,[["render",d]]);export{p as __pageData,g as default};
